using Decont;using Xunit;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Microsoft.AspNetCore.Identity;using Microsoft.Extensions.Options;using Microsoft.AspNetCore.WebUtilities;using System.Net;using System.Net.Http.Json;using System.Text.Json;using System.Text;using ClosedXML.Excel;
namespace Decont.Tests;
public class PlatformHttpTests {
 static async Task<HttpClient> Login(Factory f,string username){var c=f.CreateClient(new(){HandleCookies=true,AllowAutoRedirect=false});var csrf=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());var result=await c.PostAsJsonAsync("/api/auth/login",new{username,password="Valid-test-Password1!"});Assert.Equal(HttpStatusCode.OK,result.StatusCode);csrf=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Remove("X-CSRF-TOKEN");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());return c;}
 static void Key(HttpClient c){c.DefaultRequestHeaders.Remove("Idempotency-Key");c.DefaultRequestHeaders.Add("Idempotency-Key",Guid.NewGuid().ToString());}
 [Fact]public async Task PasswordRecoveryTokenIsSingleUseAndRevokesActiveSessions(){await using var f=new Factory();await f.Seed();var alice=await Login(f,"alice");string token,id;using(var scope=f.Services.CreateScope()){var users=scope.ServiceProvider.GetRequiredService<UserManager<User>>();var user=await users.FindByNameAsync("alice");id=user!.Id;token=WebEncoders.Base64UrlEncode(Encoding.UTF8.GetBytes(await users.GeneratePasswordResetTokenAsync(user)));}var anonymous=f.CreateClient(new(){HandleCookies=true});var csrf=await anonymous.GetFromJsonAsync<JsonElement>("/api/auth/csrf");anonymous.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());var input=new{userId=id,token,password="New-recovery-Password2!"};Assert.Equal(HttpStatusCode.OK,(await anonymous.PostAsJsonAsync("/api/auth/reset-password",input)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await alice.GetAsync("/api/me")).StatusCode);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await anonymous.PostAsJsonAsync("/api/auth/reset-password",input)).StatusCode);}
 [Fact]public async Task PasswordRecoveryRejectsExpiredTokens(){await using var f=new Factory();await f.Seed();string token,id;using(var scope=f.Services.CreateScope()){scope.ServiceProvider.GetRequiredService<IOptions<DataProtectionTokenProviderOptions>>().Value.TokenLifespan=TimeSpan.FromSeconds(-1);var users=scope.ServiceProvider.GetRequiredService<UserManager<User>>();var user=await users.FindByNameAsync("alice");id=user!.Id;token=WebEncoders.Base64UrlEncode(Encoding.UTF8.GetBytes(await users.GeneratePasswordResetTokenAsync(user)));}var client=f.CreateClient();var csrf=await client.GetFromJsonAsync<JsonElement>("/api/auth/csrf");client.DefaultRequestHeaders.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());Assert.Equal(HttpStatusCode.UnprocessableEntity,(await client.PostAsJsonAsync("/api/auth/reset-password",new{userId=id,token,password="New-recovery-Password2!"})).StatusCode);}
 [Fact]public async Task SessionRefreshesWithActivityAndExpiresAfterInactivity(){await using var f=new Factory();await f.Seed();var client=await Login(f,"alice");using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var session=await db.Sessions.SingleAsync();session.Expires=DateTime.UtcNow.AddSeconds(10);await db.SaveChangesAsync();}Assert.Equal(HttpStatusCode.OK,(await client.GetAsync("/api/me")).StatusCode);using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var session=await db.Sessions.SingleAsync();Assert.True(session.Expires>DateTime.UtcNow.AddMinutes(20));session.Expires=DateTime.UtcNow.AddSeconds(-1);await db.SaveChangesAsync();}Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync("/api/me")).StatusCode);}
 [Fact]public async Task MasterImportIsAtomicAndPreferencesAreUserScoped(){await using var f=new Factory();await f.Seed();var finance=await Login(f,"finance");Key(finance);var rows=new[]{new MasterInput("costCenters","NEW","Nou","New","{}",new(2026,1,1),null,true,"Preview"),new MasterInput("costCenters","NEW","Duplicat","Duplicate","{}",new(2026,2,1),null,true,"Preview")};Assert.Equal(HttpStatusCode.UnprocessableEntity,(await finance.PostAsJsonAsync("/api/configuration/import/confirm",new MasterBatch(rows.ToList(),"Approved import"))).StatusCode);using(var scope=f.Services.CreateScope())Assert.False(await scope.ServiceProvider.GetRequiredService<Db>().Masters.AnyAsync(m=>m.Code=="NEW"));var alice=await Login(f,"alice");Key(alice);Assert.Equal(HttpStatusCode.OK,(await alice.PutAsJsonAsync("/api/preferences/finance-filters",new{q="Private filter"})).StatusCode);var bob=await Login(f,"bob");Assert.Equal("{}",await bob.GetStringAsync("/api/preferences/finance-filters"));}
 [Fact]public void SpreadsheetRejectsFormulasAndPreservesExcelDates(){using var workbook=new XLWorkbook();var sheet=workbook.AddWorksheet("Import");sheet.Cell(1,1).Value="date";sheet.Cell(2,1).Value=new DateTime(2026,1,1);using var stream=new MemoryStream();workbook.SaveAs(stream);Assert.Equal("2026-01-01",SpreadsheetImports.Read("statement.xlsx",stream.ToArray())[1][0]);sheet.Cell(2,1).FormulaA1="1+1";using var invalid=new MemoryStream();workbook.SaveAs(invalid);Assert.Throws<DomainException>(()=>SpreadsheetImports.Read("statement.xlsx",invalid.ToArray()));}
 [Fact]public async Task CaptureCanPrecedeLinesButCannotBeUsedBeforeScanningAndUploadIsIdempotent(){await using var f=new Factory();await f.Seed();var client=await Login(f,"alice");Key(client);var created=await client.PostAsJsonAsync("/api/reports",new{purpose="OCR upload first"});var id=(await created.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();Key(client);async Task<HttpResponseMessage> Upload(){using var form=new MultipartFormDataContent();form.Add(new StringContent("1"),"version");form.Add(new ByteArrayContent(Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a16kAAAAASUVORK5CYII=")),"file","receipt.png");return await client.PostAsync($"/api/reports/{id}/capture",form);}var first=await Upload();Assert.Equal(HttpStatusCode.OK,first.StatusCode);Assert.Equal(await first.Content.ReadAsStringAsync(),await(await Upload()).Content.ReadAsStringAsync());var original=(await first.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("e").GetProperty("id").GetGuid();Key(client);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await client.PostAsJsonAsync($"/api/reports/{id}/documents/{original}/extract",new VersionRequest(2,null))).StatusCode);using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Single(await db.ReportAttachments.ToListAsync());Assert.Equal("[]",(await db.ReportAttachments.SingleAsync()).CoveredLines);}}
 [Fact]public async Task SchemaUpgradeIsRepeatableAndDatabaseProtectsAuditEvidence(){await using var f=new Factory();await f.Seed();using var scope=f.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Db>();await SchemaUpgrades.Apply(db);await SchemaUpgrades.Apply(db);db.Audits.Add(new(){Actor="Test",Entity="Test",Action="AppendOnly"});await db.SaveChangesAsync();Assert.Equal(1,await db.SchemaReleases.CountAsync(r=>r.Id==3));await Assert.ThrowsAnyAsync<Exception>(()=>db.Database.ExecuteSqlRawAsync("DELETE FROM \"Audits\""));Assert.True(await db.Audits.AnyAsync(a=>a.Action=="AppendOnly"));}
 [Fact]public async Task ReopeningPostedBatchRequiresSpecialPermissionAndReversalReference(){await using var f=new Factory();await f.Seed();var finance=await Login(f,"finance");Guid batchId;using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var employee=await db.Users.SingleAsync(u=>u.UserName=="alice");var manager=await db.Users.SingleAsync(u=>u.UserName=="manager");var r=new Report{EmployeeId=employee.Id,ManagerId=manager.Id,State=States.Posted,Purpose="Reversal test"};var batch=new Batch{ReportId=r.Id,Revision=1,State="Posted",Rows="[]",Hash="immutable",FileName="immutable.xlsx",Reference="ERP-ORIGINAL"};db.Reports.Add(r);db.Batches.Add(batch);await db.SaveChangesAsync();batchId=batch.Id;}Key(finance);Assert.Equal(HttpStatusCode.Forbidden,(await finance.PostAsJsonAsync($"/api/finance/batches/{batchId}/reopen",new ReopenInput(1,"Correction reason","ERP-REVERSAL"))).StatusCode);using(var scope=f.Services.CreateScope()){var users=scope.ServiceProvider.GetRequiredService<UserManager<User>>();await users.AddToRoleAsync((await users.FindByNameAsync("finance"))!,"FinanceReopen");}finance=await Login(f,"finance");Key(finance);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await finance.PostAsJsonAsync($"/api/finance/batches/{batchId}/reopen",new ReopenInput(1,"Correction reason",""))).StatusCode);Key(finance);Assert.Equal(HttpStatusCode.OK,(await finance.PostAsJsonAsync($"/api/finance/batches/{batchId}/reopen",new ReopenInput(1,"Correction reason","ERP-REVERSAL"))).StatusCode);using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var batch=await db.Batches.FindAsync(batchId);Assert.Equal("Reversed",batch!.State);Assert.Equal("ERP-ORIGINAL",batch.Reference);Assert.Equal("immutable.xlsx",batch.FileName);Assert.Equal(States.Reapproval,(await db.Reports.FindAsync(batch.ReportId))!.State);Assert.Single(await db.Snapshots.ToListAsync());}}

}
